-- Novas questoes ENEM enviadas pelo usuario (lote 2).
-- Cada questao aponta para sua(s) imagem(ns) de enunciado/figura.
-- Rode 0008_question_images.sql antes desta migration.

on conflict (source_ref) do update set
  subject_id=excluded.subject_id, prompt=excluded.prompt, options=excluded.options,
  correct_index=excluded.correct_index, explanation=excluded.explanation,
  difficulty=excluded.difficulty, topic=excluded.topic, question_type=excluded.question_type,
  status=excluded.status, sort_order=excluded.sort_order, source_images=excluded.source_images,
  option_images=excluded.option_images, stem_image_url=excluded.stem_image_url, exam_id=excluded.exam_id, year=excluded.year
;